mapper.select:
SELECT MAX(version_no)
FROM prd_task
WHERE tenant_id = #{tenantId}
  AND file_meta_id = #{fileMetaId}
  AND deleted = 0

SELECT DATE_FORMAT(create_time, '%Y-%m-%d') AS day, COUNT(1) AS total, COALESCE(SUM(task_status = 'SUCCESS'), 0) AS success, COALESCE(SUM(task_status = 'FAIL'), 0) AS fail FROM prd_task WHERE deleted = 0 AND create_time >= #{startTime}
AND tenant_id = #{tenantId}
GROUP BY DATE_FORMAT(create_time, '%Y-%m-%d') ORDER BY day
